import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Ghost, ArrowRight } from 'lucide-react';
import GhostCursor from '../components/GhostCursor';

function LandingPage() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-horror-black relative overflow-hidden">
      {/* Optimized Ghost Cursor - Reduced settings for smooth performance */}
      <GhostCursor
        color="#8b0000"
        brightness={0.9}
        edgeIntensity={0.1}
        trailLength={35}
        inertia={0.45}
        grainIntensity={0.03}
        bloomStrength={0.08}
        bloomRadius={0.8}
        bloomThreshold={0.03}
        fadeDelayMs={800}
        fadeDurationMs={1200}
        maxDevicePixelRatio={0.4}
        zIndex={5}
      />

      {/* Background Effects */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 blood-splatter opacity-20 animate-float"></div>
        <div className="absolute bottom-1/4 right-1/4 w-64 h-64 blood-splatter opacity-15 animate-float" style={{ animationDelay: '2s' }}></div>
      </div>

      {/* Main Content */}
      <div className="relative z-10 min-h-screen flex flex-col items-center justify-center px-4">
        <div className="text-center max-w-3xl">
          {/* Ghost Icon */}
          <div className="mb-8 animate-pulse-slow">
            <Ghost className="w-24 h-24 mx-auto text-horror-red text-glow-red" />
          </div>

          {/* Title */}
          <h1 className="font-horror text-5xl md:text-7xl text-gray-100 text-glow mb-4 tracking-wider">
            Whispers in the Dark
          </h1>

          {/* Tagline */}
          <p className="text-horror-muted text-lg md:text-xl font-body mb-4">
            Where nightmares come alive...
          </p>
          <p className="text-gray-500 text-sm md:text-base font-body mb-12 max-w-xl mx-auto">
            Share your darkest encounters. Read tales that will haunt your sleep. 
            Once you enter, you can never truly leave.
          </p>

          {/* Enter Button */}
          <button
            onClick={() => navigate('/app')}
            className="group relative inline-flex items-center gap-3 px-8 py-4 bg-transparent border-2 border-horror-red text-horror-red font-horror text-xl tracking-wider rounded transition-all duration-500 hover:bg-horror-red hover:text-white hover:shadow-[0_0_30px_rgba(139,0,0,0.5)]"
          >
            <span>Enter the Darkness</span>
            <ArrowRight className="w-5 h-5 transition-transform duration-300 group-hover:translate-x-1" />
          </button>

          {/* Warning Text */}
          <p className="mt-8 text-horror-blood/60 text-xs font-body italic">
            Warning: Some stories may disturb sensitive viewers
          </p>
        </div>
      </div>

      {/* Fog Effect */}
      <div className="fog"></div>

      {/* Corner Decorations */}
      <div className="fixed top-0 left-0 w-32 h-32 border-l-2 border-t-2 border-horror-red/20 pointer-events-none"></div>
      <div className="fixed top-0 right-0 w-32 h-32 border-r-2 border-t-2 border-horror-red/20 pointer-events-none"></div>
      <div className="fixed bottom-0 left-0 w-32 h-32 border-l-2 border-b-2 border-horror-red/20 pointer-events-none"></div>
      <div className="fixed bottom-0 right-0 w-32 h-32 border-r-2 border-b-2 border-horror-red/20 pointer-events-none"></div>
    </div>
  );
}

export default LandingPage;
